mapper.insert:
update ${database.prefix.payment}hou_pay_user_resource
set user_money = user_money + #{fixedRewards}
where user_id = #{userId}

mapper.update:
update ${database.prefix.userms}hou_user_vk set tg_num = tg_num + 1
where user_id in

    #{userId}

update ${database.prefix.userms}hou_user_vk set tg_num = if(tg_num - 1 < 0, 0, tg_num - 1)
where user_id in

    #{userId}

mapper.select:
select uiv.user_id, ui.user_name, ui.user_mobile, uid.user_gender as sex, if(uiv.one_inviter = #{param.userId},1,2) as userType, if(uv.id is null,0,1) as isVkUser, uv.create_time as vkCreateTime, uv.tg_num, ui.create_time as createTime from ${database.prefix.userms}hou_user_inviter uiv left join ${database.prefix.userms}hou_user_vk uv on uv.user_id = uiv.user_id left join ${database.prefix.userms}hou_user_info ui on ui.user_id = uiv.user_id left join ${database.prefix.userms}hou_user_info_detail uid on uid.user_id = uiv.user_id
and (uiv.one_inviter = #{param.userId} or uiv.two_inviter = #{param.userId})
and uiv.one_inviter = #{param.userId}
and uiv.two_inviter = #{param.userId}
and ui.user_name LIKE CONCAT('%', #{param.userName},'%')
and ui.user_mobile LIKE CONCAT('%', #{param.mobile},'%')

select ui.user_id, ui.user_name, ui.user_mobile, uid.user_gender as userSex, uid.user_avatar as userAvatar, ui.create_time, uv.tg_num from ${database.prefix.userms}hou_user_info ui left join ${database.prefix.userms}hou_user_info_detail uid on uid.user_id = ui.user_id left join ${database.prefix.userms}hou_user_vk uv on uv.user_id = ui.user_id left join ${database.prefix.userms}hou_user_inviter uiv on uiv.user_id = ui.user_id where (uiv.one_inviter = #{param.userId} or uiv.two_inviter = #{param.userId})
and ui.user_name LIKE CONCAT('%', #{param.userName},'%') or ui.user_nickname LIKE CONCAT('%', #{param.userName},'%')
and (uiv.one_inviter = #{param.userId} or uiv.two_inviter = #{param.userId})
and uiv.one_inviter = #{param.userId}
and uiv.two_inviter = #{param.userId}
and DATE(STR_TO_DATE(uiv.create_time, '%Y-%m-%d')) = DATE(STR_TO_DATE(now(), '%Y-%m-%d'))

select count(distinct oc.goods_id)
from ${database.prefix.order}hou_order_commission oc
where oc.share_user_id = #{userId}
